import { configureFixtureWindow } from './electron-test-environment.mjs';
import { app, BrowserWindow } from 'electron';
import { writeFileSync } from 'node:fs';
const url = process.argv.find((argument) => argument.startsWith('http://'));
if (!url || !process.env.LINGXI_TEST_USER_DATA) throw new Error('fixture URL and isolated user data required');
app.setPath('userData', process.env.LINGXI_TEST_USER_DATA);
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
async function main() {
  await app.whenReady();
  const window = new BrowserWindow({ show: false, width: 1440, height: 1000, webPreferences: { sandbox: true, backgroundThrottling: false } });
  try {
    await window.loadURL(url);
    await configureFixtureWindow(window);
    const run = (script) => window.webContents.executeJavaScript(script);
    const wait = async (expression) => {
      const deadline = Date.now() + 6000;
      while (Date.now() < deadline) { if (await run(expression)) return; await delay(20); }
      throw new Error(`Timed out: ${expression}\n${await run('document.body.innerText')}`);
    };
    const click = async (text) => {
      const expression = `[...document.querySelectorAll('button')].find(b => b.getClientRects().length && b.textContent.trim().replace(/→$/, '').trim() === ${JSON.stringify(text)})`;
      await wait(`Boolean(${expression})`);
      await run(`${expression}.click()`);
      await delay(30);
    };
    const state = () => run('window.scheduledCronFixture.state()');
    const setTitle = async (value) => {
      await run(`(() => { const input = document.querySelector('.scheduled-setup-title'); Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(input, ${JSON.stringify(value)}); input.dispatchEvent(new Event('input', {bubbles:true})); })()`);
      await delay(30);
    };
    await wait("Boolean(document.querySelector('.scheduled-suggestion'))");
    await run("[...document.querySelectorAll('.scheduled-suggestion')].find(b => b.textContent.includes('Weekly review')).click()");
    await wait("Boolean(document.querySelector('[aria-label=\"Editable task details\"]'))");
    const picker = {};
    const clickLabel = async (label) => {
      await run(`document.querySelector('button[aria-label=${JSON.stringify(label)}]').click()`);
      await delay(30);
    };
    const setTime = async (label, value) => {
      await run(`(() => { const input = document.querySelector('dialog[open] input[aria-label=${JSON.stringify(label)}]'); Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(input, ${JSON.stringify(value)}); input.dispatchEvent(new Event('input', {bubbles:true})); })()`);
      await delay(30);
    };
    const capturePicker = async (name) => {
      if (process.env.LINGXI_PICKER_SCREENSHOT) writeFileSync(`${process.env.LINGXI_PICKER_SCREENSHOT}-${name}.png`, (await window.webContents.capturePage()).toPNG());
    };
    await clickLabel('At');
    await wait(`Boolean(document.querySelector('dialog[open][aria-label="At"]'))`);
    await setTime('Hour', '24');
    await click('Done');
    picker.invalidHourBlocked = await run('Boolean(document.querySelector("dialog[open]"))');
    await setTime('Hour', '18');
    await setTime('Minute', '25');
    await capturePicker('time-light');
    await click('Done');
    await wait('!document.querySelector("dialog[open]")');
    await wait('document.activeElement?.getAttribute("aria-label") === "At"');
    picker.doneFocus = await run('document.activeElement?.getAttribute("aria-label")');
    picker.timeDescription = await run('document.getElementById(document.activeElement.getAttribute("aria-describedby"))?.textContent');
    await clickLabel('At');
    await run('document.querySelector("dialog[open] input").focus()');
    window.webContents.sendInputEvent({type: 'keyDown', keyCode: 'Escape'});
    window.webContents.sendInputEvent({type: 'keyUp', keyCode: 'Escape'});
    await wait('!document.querySelector("dialog[open]")');
    await wait('document.activeElement?.getAttribute("aria-label") === "At"');
    picker.escapeFocus = await run('document.activeElement?.getAttribute("aria-label")');
    await run(`(() => { const input = [...document.querySelectorAll('label')].find(item => item.firstChild?.textContent === 'Expires').querySelector('select'); input.value = 'date'; input.dispatchEvent(new Event('change', {bubbles:true})); })()`);
    await delay(30);
    await clickLabel('End date');
    await clickLabel('Next month');
    const lastDay = await run('[...document.querySelectorAll("dialog[open] .lx-date-calendar button")].at(-1).getAttribute("aria-label")');
    await clickLabel(lastDay);
    await run(`document.querySelector('dialog[open] button[aria-label="${lastDay}"]').dispatchEvent(new KeyboardEvent('keydown', {key:'ArrowRight', bubbles:true}))`);
    await delay(50);
    const selectedDay = await run(`document.querySelector('dialog[open] button[aria-pressed="true"]').getAttribute('aria-label')`);
    picker.monthRollover = selectedDay.endsWith('-01') && selectedDay.slice(0, 7) !== lastDay.slice(0, 7);
    picker.calendarFocus = await run('document.activeElement?.getAttribute("aria-label")') === selectedDay;
    await clickLabel('Previous month');
    picker.previousMonth = await run(`Boolean(document.querySelector('dialog[open] button[aria-label="${lastDay}"]'))`);
    await clickLabel('Next month');
    await setTime('Hour', '10');
    await setTime('Minute', '45');
    picker.expectedExpiry = await run(`new Date('${selectedDay}T10:45').getTime()`);
    picker.calendarTabStops = await run('[...document.querySelectorAll("dialog[open] .lx-date-calendar button")].filter(button => button.tabIndex === 0).length');
    await capturePicker('calendar-light');
    await run('window.scheduledCronFixture.setDark(true)');
    await capturePicker('calendar-dark');
    window.setSize(500, 900);
    await delay(100);
    picker.narrowFits = await run('(() => { const rect = document.querySelector("dialog[open]").getBoundingClientRect(); return rect.left >= 0 && rect.right <= innerWidth && rect.top >= 0 && rect.bottom <= innerHeight; })()');
    await capturePicker('calendar-narrow');
    window.setSize(1440, 1000);
    await run('window.scheduledCronFixture.setDark(false)');
    await click('Done');
    await clickLabel('At');
    await run(`document.querySelector('dialog[open] input[aria-label="Hour"]').focus()`);
    window.webContents.sendInputEvent({type: 'keyDown', keyCode: 'Enter'});
    window.webContents.sendInputEvent({type: 'keyUp', keyCode: 'Enter'});
    await delay(80);
    picker.enterCloses = await run('!document.querySelector("dialog[open]")');
    if ((await state()).jobs.length) throw new Error('Enter in the time picker submitted the outer task form');
    if (!picker.enterCloses) throw new Error('Enter in the time picker did not close it');
    await click('Create task');
    await wait("document.querySelectorAll('.scheduled-job').length === 1");
    const result = { created: await state(), picker };
    await run("document.querySelector('.scheduled-job').click()");
    await wait("Boolean(document.querySelector('.scheduled-setup-title'))");
    await setTitle('Edited weekly review');
    await click('Save changes');
    await wait("Boolean(document.querySelector('.scheduled-job'))");
    await run("document.querySelector('.scheduled-job').click()");
    await wait("Boolean(document.querySelector('.scheduled-setup-title'))");
    result.reopenedTitle = await run("document.querySelector('.scheduled-setup-title').value");
    const select = async (label, value) => {
      await run(`(() => { const field = [...document.querySelectorAll('label')].find(item => item.firstChild?.textContent === ${JSON.stringify(label)}); const input = field.querySelector('select'); input.value = ${JSON.stringify(value)}; input.dispatchEvent(new Event('change', {bubbles:true})); })()`);
      await delay(30);
    };
    await select('Runs in', 'selected_session');
    await select('Chat', 'fixture-session');
    await select('Reasoning', JSON.stringify({type:'level',id:'high'}));
    await select('Notifications', 'failed');
    await select('Status', 'paused');
    await click('Save changes');
    await wait("window.scheduledCronFixture.state().jobs[0]?.automation?.status === 'paused'");
    result.configured = await state();
    await click('Active');
    result.activeCount = await run("document.querySelectorAll('.scheduled-job').length");
    await click('Paused');
    result.pausedCount = await run("document.querySelectorAll('.scheduled-job').length");
    await click('All');

    await setTitle('Unsaved title');
    const beforeDirtyPoll = (await state()).requests.length;
    await run('window.scheduledCronFixture.tickRefresh()');
    await delay(40);
    result.dirtyPollRequests = (await state()).requests.length - beforeDirtyPoll;
    await run("window.scheduledCronFixture.rejectNext('Fixture backend rejected save')");
    await click('Save changes');
    await wait("Boolean(document.querySelector('[role=alert]'))");
    result.rejected = await run("({error:document.querySelector('[role=alert]').textContent,title:document.querySelector('.scheduled-setup-title').value,state:window.scheduledCronFixture.state()})");
    await run("document.querySelector('.scheduled-setup-back').click()");
    await wait("Boolean(document.querySelector('.scheduled-job'))");
    await click('Discard changes');
    await run("document.querySelector('.scheduled-job').click()");
    await click('Delete task');
    if ((await state()).jobs.length !== 1) throw new Error('Delete must require confirmation');
    await click('Confirm delete');
    await wait("document.querySelectorAll('.scheduled-job').length === 0");
    result.deleted = await state();
    await run('window.scheduledCronFixture.addExternal()');
    await click('Refresh');
    await wait("document.querySelectorAll('.scheduled-job').length === 1");
    result.refreshed = await state();
    await run("document.querySelector('.scheduled-job').click()");
    await wait("Boolean(document.querySelector('.scheduled-setup-title'))");
    await setTitle('Saved during navigation');
    const offset = (await state()).requests.length;
    await run('window.scheduledCronFixture.holdMutation()');
    await click('Save changes');
    await run('window.scheduledCronFixture.setVisible(false)');
    await run('window.scheduledCronFixture.setVisible(true)');
    await delay(50);
    result.duringMutation = (await state()).requests.slice(offset).map((request) => request.action);
    await run('window.scheduledCronFixture.releaseMutation()');
    await wait("document.querySelector('.scheduled-job')?.textContent.includes('Saved during navigation')");
    await wait("![...document.querySelectorAll('button')].find(b => b.textContent === 'Save changes')?.disabled");
    await delay(150);
    if (process.env.LINGXI_SCHEDULED_SCREENSHOT) writeFileSync(process.env.LINGXI_SCHEDULED_SCREENSHOT, (await window.webContents.capturePage()).toPNG());
    await click('Copy to project');
    await wait("Boolean([...document.querySelectorAll('button')].find(b => b.textContent === 'Create task' && !b.disabled))");
    result.copyDraft = await run("({mode:[...document.querySelectorAll('label')].find(l=>l.firstChild?.textContent==='Runs in').querySelector('select').value, projectEditable:![...document.querySelectorAll('label')].find(l=>l.firstChild?.textContent==='Project').querySelector('select').disabled})");
    await click('Create task');
    await wait("window.scheduledCronFixture.state().jobs.length === 2");
    await click('Run history');
    await wait("document.querySelector('.scheduled-history')?.textContent.includes('No runs yet.')");
    result.copied = await state();
    await run("window.scheduledCronFixture.completeJob(window.scheduledCronFixture.state().jobs.at(-1).id)");
    await run('window.scheduledCronFixture.tickRefresh()');
    await wait("document.querySelector('.scheduled-setup-header')?.textContent.includes('completed')");
    await wait("document.querySelector('.scheduled-history')?.textContent.includes('Automatic result refreshed')");
    result.pollUpdated = true;
    window.setSize(500, 900);
    await delay(150);
    result.narrow = await run("({listHidden:getComputedStyle(document.querySelector('.scheduled-master')).display === 'none', overflow:document.documentElement.scrollWidth > innerWidth})");
    if (process.env.LINGXI_SCHEDULED_SCREENSHOT) writeFileSync(process.env.LINGXI_SCHEDULED_SCREENSHOT.replace('.png','-narrow.png'), (await window.webContents.capturePage()).toPNG());
    process.stdout.write(`${JSON.stringify(result)}\n`);
  } finally { window.destroy(); app.quit(); }
}
main().catch((error) => { process.stderr.write(`${error.stack ?? error}\n`); app.exit(1); });
